def calculate_val(row, col):
    pattern_pos = (col + row - 21) % 5
    pattern = [3, 5, 7, 9, 1]
    return pattern[pattern_pos]

output_grid = [[0]*28 for _ in range(28)]

for row in range(28):
    for col in range(28):
        if grid[row][col] != 0:
            output_grid[row][col] = grid[row][col]
        elif 11 <= col <= 17:
            output_grid[row][col] = calculate_val(row, col)

# Print submission as JSON
import json
print(json.dumps({"action": "submit", "grid": output_grid}))

# Let me understand the full grid structure and what needs filling
# The test input has zones that need to be mentally completed

def get_pattern_at_col(col, row):
    """Get value using the formula that worked for rows 3-8 and row 20"""
    pattern = [3, 5, 7, 9, 1]
    pattern_pos = (col - 18 + (row - 3)) % 5
    return pattern[pattern_pos]

# Build the completed grid
output_grid = [[0]*28 for _ in range(28)]

for row in range(28):
    for col in range(28):
        if grid[row][col] != 0:
            output_grid[row][col] = grid[row][col]
        else:
            # Fill with pattern
            output_grid[row][col] = get_pattern_at_col(col, row)

# Verify against test input that non-zero cells are preserved
print("Verifying non-zero cells preserved:")
for row in range(28):
    for col in range(28):
        if grid[row][col] != 0 and output_grid[row][col] != grid[row][col]:
            print(f"MISMATCH at ({row},{col}): input={grid[row][col]}, output={output_grid[row][col]}")
print("Done checking")

# Print a few complete rows
print("\nOutput grid rows:")
for row in [0, 3, 8, 14, 20, 27]:
    print(f"Row {row}: {' '.join(map(str, output_grid[row]))}")

# Check for any remaining zeros in the output
print("\nChecking for remaining zeros:")
for row in range(28):
    if any(c == 0 for c in output_grid[row]):
        zeros = [c for c in range(28) if output_grid[row][c] == 0]
        print(f"Row {row} has zeros at: {zeros[:10]}...")

# Okay let me use the proven formula from rows 8, 10, 18, 20, 27 and fill the 0s
# Formula: pattern_pos = (col - 3 + row) % 5 with pattern = [3, 5, 7, 9, 1]
# Fill all 0s, keep non-zero values as-is

pattern = [3, 5, 7, 9, 1]

def calc_pattern(row, col):
    pos = (col - 3 + row) % 5
    return pattern[pos]

# Build output grid
output = [[grid[r][c] for c in range(28)] for r in range(28)]

for r in range(28):
    for c in range(28):
        if grid[r][c] == 0:
            output[r][c] = calc_pattern(r, c)

# Count changes
changes = 0
for r in range(28):
    for c in range(28):
        if grid[r][c] == 0 and output[r][c] != 0:
            changes += 1

print(f"Filled {changes} zeros with pattern values")

# Verify formula against complete rows (rows with no 0s in middle)
print("\nVerification against rows with complete patterns:")
for row in [8, 18, 20, 27]:
    match = True
    for c in range(28):
        if grid[row][c] == 0:
            continue
        expected = calc_pattern(row, c)
        if grid[row][c] != expected:
            match = False
            print(f"  MISMATCH at row {row}, col {c}: expected {expected}, got {grid[row][c]}")
            break
    if match:
        print(f"  Row {row}: all matches ✓")

# Submit
import json
output_json = {"action": "submit", "grid": output}
print("\nSubmitting...")
print(json.dumps(output_json))

